WITH "g1" AS (SELECT "t1"."region" AS "region", SUM(CASE WHEN "t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00' THEN "t0"."net_amount" END) AS "revenue" FROM "sales"."orders" AS "t0" LEFT JOIN "sales"."branches" AS "t1" ON "t0"."branch_id" = "t1"."branch_id" WHERE ("t0"."status" = 'DONE') AND ("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00') GROUP BY "t1"."region"), "calc" AS (SELECT "g1"."region" AS "region", "g1"."revenue" AS "revenue", ("g1"."revenue" - AVG("g1"."revenue") OVER ()) AS "vs_avg" FROM "g1") SELECT "calc"."region" AS "region", "calc"."revenue" AS "revenue", "calc"."vs_avg" AS "vs_avg" FROM "calc" WHERE "calc"."vs_avg" > 0 ORDER BY "revenue" DESC LIMIT 1000
